        messages["readmeSummaryCreated"] = "Created mods: {0}";
        messages["readmeSummarySkipped"] = "Skipped files: {0}";
        messages["readmeSummaryIntro"] = "Each child folder with `modinfo.json` is a standalone Mod Loader mod. Template folders are for browsing only.";
        messages["readmeSummaryGuide"] = "Read **[MODDING-GUIDE.md](MODDING-GUIDE.md)** for install paths, ModOps, testing, and publishing.";
        messages["readmeSummaryIndex"] = "Open `INDEX.md` inside a template folder to browse assets by GUID and display name.";
        messages["readmeSummarySingle"] = "Single-GUID export: one mod in this folder plus the shared modding guide.";
        messages["readmeWhatIsHeader"] = "## Glossary";
        messages["readmeWhatIsAsset"] = "- **Asset**: Everything in Anno is an asset — a building, an item, a specialist, a fertility, a product. Each has a unique numeric GUID and is defined in XML.";
        messages["readmeWhatIsGuid"] = "- **GUID**: A unique number that identifies one specific asset. The Mod Loader uses it to know which asset to patch. Find GUIDs at a1800.net.";
        messages["readmeWhatIsTemplate"] = "- **Template**: The type of asset (e.g. `Item`, `Fertility`, `FactoryBuilding7`). Templates define the default properties an asset inherits. Think of it as the asset's category.";
        messages["readmeWhatIsModLoader"] = "- **Mod Loader**: A community tool that loads mods when the game starts. It reads your mod folder, finds `modinfo.json`, and merges your `assets.xml` changes into the game's data.";
        messages["readmeWhatIsModOp"] = "- **ModOp (Mod Operation)**: An XML instruction that tells the Mod Loader what to change. It has a Type (what to do), GUID (which asset), and Path (where in that asset's XML to work).";
        messages["readmeWhatIsModinfo"] = "- **modinfo.json**: A file at the root of every mod that tells the Mod Loader what this mod is called, who made it, and how it relates to other mods.";
        messages["readmeWhatIsXPath"] = "- **XPath/Path**: A way to navigate inside XML. Like a folder path (`/Values/Standard/Name`) that points to a specific place in the asset's data tree.";
        messages["readmeWhatIsModOpsWrapper"] = "- **`<ModOps>` vs `<ModOp>`**: `<ModOps>` is the outer wrapper (one per file). Inside it, you put one or more `<ModOp>` entries — each one performs a single change.";
        messages["readmeWhatIsFlow"] = "- **How it works**: Game starts → Mod Loader scans your mod folder → reads `modinfo.json` → loads `assets.xml` → merges your `<ModOps>` patches on top of the game's original data → game runs with your changes.";
        messages["readmeXPathHeader"] = "## XPath Tree Guide";
        messages["readmeXPathIntro"] = "Every asset is a tree of XML nodes. Paths navigate this tree to find the exact spot you want to change:";
        messages["readmeXPathTree"] = "Asset root → `/` (top of asset, rarely used)\n  └── Template → `/Template` (the asset type, e.g. Item, Fertility)\n  └── Values → `/Values` (where all properties live)\n      └── Standard → `/Values/Standard` (GUID, name, icon etc.)\n      │   ├── GUID → `/Values/Standard/GUID`\n      │   └── Name → `/Values/Standard/Name`\n      └── Product → `/Values/Product` (production properties)\n      │   └── Amount → `/Values/Product/Amount`\n      └── Item → `/Values/Item` (item-specific properties)\n          ├── Rarity → `/Values/Item/Rarity`\n          └── MaxStackSize → `/Values/Item/MaxStackSize`\n\nShortcut: `GUID=\"123\"` is the same as `//Asset[Values/Standard/GUID='123']`\nAnno 117 short paths skip `/Values/` — `Merge=\"Standard/Name\"` equals `Path=\"/Values/Standard/Name\"`";
        messages["readmeXPathExamples"] = "- To change a name: `Path=\"/Values/Standard/Name\"`\n- To change productivity: `Path=\"/Values/FactoryUpgrade/ProductivityUpgrade/Value\"`\n- To add a new child under Item: `Path=\"/Values/Item\"` (with Type=add)\n- To insert after Standard: `Path=\"/Values/Standard\"` (with Type=addNextSibling)\n- To remove a cost node: `Path=\"/Values/Cost\"` (with Type=remove)\n- To target every asset on an island: `Path=\"//Asset[Values/Building/Island='123']\"`";
