        messages["readmeAnno117Install"] = "- Install location: copy the mod folder into `<user>/Anno 117/mods/` or `<install>/Anno 117/mods/`.";
        messages["readmeAnno117Modinfo"] = "- `modinfo.json` is required. Anno 117 only loads mods when `modinfo.json` has `Anno: 8`.";
        messages["readmeAnno117GameSetup"] = "- Anno 117 requires `Difficulty` and uses `GameSetup` for savegame, multiplayer, campaign, and safe-to-remove metadata.";
        messages["readmeAnno117AssetsPath"] = "- Anno 117 uses `data/base/config/export/assets.xml` for asset XML patches.";
        messages["readmeAnno117ShortModOps"] = "- Anno 117 supports newer short ModOps such as `GUID=\"123\" Merge=\"Standard\"`; those omit the `/Values/` part.";
        messages["readmeAnno117LegacyModOps"] = "- Anno 117 can also use legacy ModOps with `Type=\"merge\"` and `Path=\"/Values/...\"`, which is what Asset Splitter writes for compatibility.";
        messages["readmeAnno117Profile"] = "- To control activation, edit `<user>/Anno 117/mods/active-profile.txt`; prefix a mod entry with `#` to disable it.";
        messages["readmeAnno117FolderDisable"] = "- You can also disable Anno 117 folders by prefixing the folder name with `-`, but the profile file is the recommended method.";
        messages["readmeAnno117EnableNew"] = "- Prefix `EnableNewMods` with `#` in `active-profile.txt` if you want newly detected mods disabled by default.";
        messages["readmeAnno117Deps"] = "- The Anno 117 dependency fields live under `Dependencies`: `Require`, `Optional`, `LoadAfter`, `Deprecate`, and `Incompatible`.";
        messages["readmeAnno117Log"] = "- The Anno 117 mod-loader log is in `<user>/Anno 117/mods/mod-loader.log`.";
        messages["readmeAnno117HotReload"] = "- Anno 117 ships with a Hot Reload mod in `<game>/mods/.ubi/hot-reload-ubi/`. When enabled, mod changes are picked up without restarting the game.";
        messages["readmeAnno1800Install"] = "- Install location: copy the mod folder into `<user>/Anno 1800/mods/` or `<install>/Anno 1800/mods/`.";
        messages["readmeAnno1800Fallback"] = "- Local Anno 1800 mods can fall back to the folder name if `ModID` or `modinfo.json` is missing, but Asset Splitter writes `modinfo.json` and `ModID` so tools and dependencies behave predictably.";
        messages["readmeAnno1800AssetsPath"] = "- Anno 1800 uses `data/config/export/main/asset/assets.xml` for asset XML patches.";
        messages["readmeAnno1800LegacyModOps"] = "- Anno 1800 must use legacy ModOps with `Type=\"...\"` and `Path=\"...\"`; do not use the Anno 117 short `Merge=\"...\"`, `Add=\"...\"`, `Remove=\"...\"`, `Append=\"...\"`, or `Prepend=\"...\"` style.";
        messages["readmeAnno1800PathNote"] = "- In Anno 1800 legacy paths include `/Values/...`; the short Anno 117 paths intentionally skip `/Values/`.";
        messages["readmeAnno1800AnnoField"] = "- `Anno: 7` is optional for local Anno 1800 mods, but Asset Splitter writes it because it helps tools identify the game.";
        messages["readmeAnno1800Activation"] = "- To control activation, prefix the mod folder or zip with `-`, or add the mod id to `<mods>/activation.json` under `disabledIds`. Anno 1800 does not use Anno 117's `active-profile.txt`.";
        messages["readmeAnno1800Zip"] = "- Anno 1800 can also load mods from `.zip` files, but island files can be problematic from zips.";
        messages["readmeAnno1800Deps"] = "- Anno 1800 dependency fields are `ModDependencies`, `OptionalDependencies`, `LoadAfterIds`, `DeprecateIds`, and `IncompatibleIds`.";
        messages["readmeAnno1800Log"] = "- The Anno 1800 mod-loader log is in `<user documents>/Anno 1800/log/mod-loader.log`.";
        messages["readmeAnno1800NoHotReload"] = "- Anno 1800 does not support hot reload. You must restart the game to see mod changes.";
